type CompleteActivationArguments = [
  owner: DependencyOwner,
  request: CompleteDependencyActivationRequest,
  layouts: SolverLayouts,
  deadline: number,
  directory: string,
  ports: CompleteActivationTransports,
];
type CompleteActivationPacket = Awaited<ReturnType<typeof activateCompleteBody>>;
function activateCompleteUnderOwner(
  args: CompleteActivationArguments,
  purpose: 'fenced',
): Promise<CompleteDependencyActivationCompletion>;
function activateCompleteUnderOwner(
  args: CompleteActivationArguments,
  purpose: 'restoration' | 'initial-handoff',
): Promise<PreparedDependencyActivation>;
/** Synchronously reserves the real composition before its private body can acquire anything. */
function activateCompleteUnderOwner(
  args: CompleteActivationArguments,
  purpose: 'fenced' | 'restoration' | 'initial-handoff',
): Promise<CompleteDependencyActivationCompletion | PreparedDependencyActivation> {
  try {
    const preparation = enrollDependencyPreparation(args[0], {
      layouts: [args[2].prod, args[2].dev],
      deadline: args[3],
      purpose,
    });
    const body = bindPreparationComposition(
      preparation,
      activateCompleteBody(...args, purpose, preparation),
    );
    if (purpose === 'fenced')
      return bindPreparationProjection(preparation, projectFencedCompletion(preparation, body));
    return bindPreparationProjection(preparation, projectPreparedCompletion(preparation, body));
  } catch (cause) {
    return Promise.reject(cause);
  }
}
async function projectFencedCompletion(
  preparation: DependencyPreparation,
  body: Promise<CompleteActivationPacket>,
): Promise<CompleteDependencyActivationCompletion> {
  await Promise.allSettled([body]);
  await assertPreparationCompletion(preparation);
  return (await body).completion;
}
async function projectPreparedCompletion(
  preparation: DependencyPreparation,
  body: Promise<CompleteActivationPacket>,
): Promise<PreparedDependencyActivation> {
  await Promise.allSettled([body]);
  await assertPreparationCompletion(preparation);
  const packet = await body;
  if (packet.prepared === undefined) throw new Error('finalized activation preparation absent');
  return packet.prepared;
}
/** Frozen fenced-only composition. It never retains a participant restoration grant or starts participants. */
export function activateCompleteDependenciesUnderOwner(
  ...args: CompleteActivationArguments
