import { readFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { expect, test } from 'bun:test';
const root = '/home/df/.codex/worktrees/1b31/puni-00';
const fixturePath = root + '/tools/tool-remote-scripts/src/fixtures/dependency-owner-custody.ts';
const storagePath = root + '/tools/tool-remote-scripts/src/lib/dependency-activation-storage.test.ts';
const sha = (bytes: string | Uint8Array) => createHash('sha256').update(bytes).digest('hex');
const storage = readFileSync(storagePath, 'utf8');
if (sha(storage) !== '05f05c0befacbdbaecf34e9e68ba4e5bd719d0c43a251dc5e3673db6a3457acb') throw Error('storage source changed');
const start = storage.indexOf('function compileActualPrehelperImage(');
const end = storage.indexOf('/** Extracts current private custody cuts;', start);
if (start < 0 || end <= start) throw Error('compiler declaration boundary differs');
const emitted = new Bun.Transpiler({loader:'ts'}).transformSync(storage.slice(start,end) + '\nexport { compileActualPrehelperImage };');
const namespace = await import('data:text/javascript;base64,' + Buffer.from(emitted).toString('base64'));
if (typeof namespace.compileActualPrehelperImage !== 'function') throw Error('pure compiler absent');
test('final input closure leaves historical invalid-build image byte-identical', () => {
  const current = readFileSync(fixturePath);
  const original = readFileSync('/tmp/puni-storage-extraction-fixture.ts');
  expect(sha(current)).toBe('a49d7d4e9b19ece6fcaced543e6371dd42965c4be8e3b618b0a8e7f8fb1ee2ba');
  expect(sha(original)).toBe('d8e705f3e1625f34765591ce7f42141dcbfd3474957c211ef58e5f14a308d90c');
  expect(sha(current.subarray(0,95701))).toBe('50281b36a01665b83062e7bb7d065361037182581fb791a89e1b049d65cf4b04');
  expect(current.subarray(0,95701).equals(original.subarray(0,95701))).toBe(true);
  const ordinaryStart = "\nimport { realpath as ordinaryHoldRealpath } from 'node:fs/promises';";
  expect(current.toString().split(ordinaryStart).length).toBe(2);
  const currentImage = namespace.compileActualPrehelperImage(current.toString());
  const originalImage = namespace.compileActualPrehelperImage(original.toString());
  expect(currentImage).toBe(originalImage);
  console.log(JSON.stringify({outcome:'pure-prefix-equal',fixtureSha256:sha(current),storageSha256:sha(storage),emittedHistoricalBytes:Buffer.byteLength(currentImage),emittedHistoricalSha256:sha(currentImage),generatedImageImported:false,actualBuildCalled:false}));
});

